List<int> orderIds = [1, 2, 3];
try
{
    // ForEach takes an Action<int>, so this lambda is async void
    orderIds.ForEach(async id => await SaveOrderAsync(id));
    Console.WriteLine("Import complete"); // printed before any save ends
}
catch (Exception ex)
{
    Console.WriteLine($"Import failed: {ex.Message}"); // never runs
}

static async Task SaveOrderAsync(int id)
{
    await Task.Delay(100); // stands in for the database call
    if (id == 2) throw new InvalidOperationException($"Order {id} rejected");
}

List<int> orderIds = [1, 2, 3];
try
{
    // Select gives Func<int, Task>: one Task per order, all awaited
    await Task.WhenAll(orderIds.Select(SaveOrderAsync));
    Console.WriteLine("Import complete"); // only after every save
}
catch (Exception ex)
{
    Console.WriteLine($"Import failed: {ex.Message}"); // Order 2 rejected
}

static async Task SaveOrderAsync(int id)
{
    await Task.Delay(100); // stands in for the database call
    if (id == 2) throw new InvalidOperationException($"Order {id} rejected");
}

