public class ExportButton(ILogger<ExportButton> logger)
{
    public async void OnClick(object? sender, EventArgs e)
    {
        try
        {
            await ExportAsync(); // the real logic returns a Task
        }
        catch (Exception ex)
        {
            logger.LogError(ex, "Export failed");
        }
    }

    public async Task ExportAsync() => await Task.Delay(100);
}
